/** A pane's existing screen parts. App code owns the scroll state inside [content]. */
@Immutable
data class SbAppPane(
    val title: String,
    val topBar: @Composable (showBack: Boolean, showSign: Boolean) -> Unit,
    val content: @Composable (PaddingValues) -> Unit,
    val primaryAction: SbPrimaryActionModel? = null,
    val secondaryAction: (@Composable () -> Unit)? = null,
    val snackbarHost: @Composable () -> Unit = {},
    val statusText: String? = null,
)

/**
 * Adaptive, content-width frame. A selected end pane is a phone drill-in; null is the quiet wide placeholder.
 * [productName] = the product's name as it is written, which TalkBack reads for the rail's tile; the default is the
 * product's `name` (its id in PascalCase), which is right only where both are spelt the same.
 */
@Composable
fun SbAppFrame(
    items: List<SbNavItem>,
    selectedIndex: Int,
    onSelect: (Int) -> Unit,
    product: SebaroProduct,
    glyph: Painter,
    startPane: SbAppPane,
    emptyText: String,
    modifier: Modifier = Modifier,
    endPane: SbAppPane? = null,
    split: Boolean = false,
    onBack: () -> Unit = {},
    selectedRowFocus: FocusRequester? = null,
    endBackWithinPane: Boolean = false,
    showNavigation: Boolean = true,
    phoneNavigation: Boolean = true,
    productName: String = product.name,
) {
    require(!showNavigation || items.size in 3..5) { "SbAppFrame: 3 to 5 destinations" }
    require(!showNavigation || selectedIndex in items.indices) { "SbAppFrame: invalid selection" }
    val c = SebaroTheme.colors
    val t = SebaroTheme.tokens
    val endTitleFocus = remember { FocusRequester() }
    var wasEnd by remember { mutableStateOf(false) }
    BoxWithConstraints(modifier.fillMaxSize().background(c.bg)) {
        val wide = maxWidth >= 840.dp
        val two = split || endPane != null
        val phoneEnd = !wide && endPane != null
        LaunchedEffect(phoneEnd) {
            withFrameNanos { }
            if (phoneEnd) endTitleFocus.requestFocus()
            else if (wasEnd && endPane == null) selectedRowFocus?.requestFocus()
            wasEnd = phoneEnd
        }
        BackHandler(enabled = phoneEnd, onBack = onBack)
        val safe = Modifier.windowInsetsPadding(WindowInsets.systemBars.union(WindowInsets.ime))
        val start: @Composable () -> Unit = {
            FramePane(startPane, showBack = !two || !wide, showSign = !wide || !showNavigation,
                hidePrimary = endPane?.primaryAction != null, order = 0f, wideZone = wide)
        }
        val end: @Composable () -> Unit = {
            if (endPane == null) {
                Box(Modifier.fillMaxSize().padding(horizontal = t.spacing.gutter, vertical = t.space.s6).semantics {
                    isTraversalGroup = true
                    traversalIndex = 1f
                }) { SbWrapText(emptyText, SebaroTheme.typography.body, c.textMuted) }
            } else {
                CompositionLocalProvider(LocalSbFrameTitleFocus provides if (phoneEnd) endTitleFocus else null) {
                    FramePane(endPane, showBack = !wide || endBackWithinPane, showSign = false,
                        hidePrimary = false, order = 1f, wideZone = wide)
                }
            }
        }
        if (!wide) {
            Column(safe) {
                Box(Modifier.weight(1f)) { if (phoneEnd) end() else start() }
                if (showNavigation && phoneNavigation && !phoneEnd) {
                    val hasZone = startPane.primaryAction != null || startPane.secondaryAction != null
                    SbNavigationBar(items, selectedIndex, onSelect, Modifier.semantics {
                        isTraversalGroup = true
                        traversalIndex = 2f
                    }.drawBehind {
                        if (!hasZone) drawLine(t.x.layerLineColor, Offset.Zero, Offset(size.width, 0f), t.x.layerLineWidth.toPx())
                    })
                }
            }
        } else {
            // Child order is content first, even though the rail is placed at the start edge.
            Layout(content = {
                Box { start() }
                if (two) Box { end() }
                if (showNavigation) FrameRail(items, selectedIndex, onSelect, product, glyph, productName)
            }, modifier = safe) { measurables, constraints ->
                val rail = if (showNavigation) 96.dp.roundToPx() else 0
                val line = if (two) t.borderWidth.hairline.roundToPx() else 0
                val firstWidth = if (two) 320.dp.roundToPx() else constraints.maxWidth - rail
                fun measure(index: Int, width: Int) = measurables[index].measure(
                    Constraints.fixed(width.coerceAtLeast(0), constraints.maxHeight))
                val first = measure(0, firstWidth)
                val second = if (two) measure(1, constraints.maxWidth - rail - firstWidth - line) else null
                val nav = if (showNavigation) measure(if (two) 2 else 1, rail) else null
                layout(constraints.maxWidth, constraints.maxHeight) {
                    first.placeRelative(rail, 0)
                    second?.placeRelative(rail + firstWidth + line, 0)
                    nav?.placeRelative(0, 0)
                }
            }
            // Divider belongs to the layout, not to either scrolling pane.
            if (two) Box(safe.fillMaxSize().drawBehind {
                val x = (if (showNavigation) 96.dp else 0.dp).toPx() + 320.dp.toPx()
                val at = if (layoutDirection == LayoutDirection.Ltr) x else size.width - x
                drawLine(c.border, Offset(at, 0f), Offset(at, size.height), t.borderWidth.hairline.toPx())
            })
        }
    }
}

@Composable
private fun FramePane(pane: SbAppPane, showBack: Boolean, showSign: Boolean, hidePrimary: Boolean, order: Float, wideZone: Boolean) {
    CompositionLocalProvider(LocalSbWideActionZone provides wideZone) {
    SbScreen(topBar = { pane.topBar(showBack, showSign) }, modifier = Modifier.fillMaxSize().semantics {
        isTraversalGroup = true
        traversalIndex = order
        paneTitle = pane.title
    }, primaryAction = if (hidePrimary) null else pane.primaryAction,
        snackbarHost = pane.snackbarHost, secondaryAction = pane.secondaryAction, statusText = pane.statusText, content = pane.content)
    }
}

@Composable
private fun FrameRail(items: List<SbNavItem>, selectedIndex: Int, onSelect: (Int) -> Unit,
    product: SebaroProduct, glyph: Painter, productName: String) {
    val c = SebaroTheme.colors
    val t = SebaroTheme.tokens
    val ty = SebaroTheme.typography
    val direction = LocalLayoutDirection.current
    val focuses = remember(items.size) { List(items.size) { FocusRequester() } }
    Column(Modifier.width(96.dp).fillMaxSize().semantics {
        isTraversalGroup = true
        traversalIndex = 2f
    }.selectableGroup().drawBehind {
        val x = if (layoutDirection == LayoutDirection.Ltr) size.width else 0f
        drawLine(c.border, Offset(x, 0f), Offset(x, size.height), t.borderWidth.hairline.toPx())
    }.verticalScroll(rememberScrollState())) {
        Box(Modifier.fillMaxWidth().padding(vertical = 16.dp), contentAlignment = Alignment.Center) {
            SbSignTile(product, glyph, productName, size = 32.dp)
        }
        items.forEachIndexed { index, item ->
            val selected = index == selectedIndex
            val interaction = remember { MutableInteractionSource() }
            val ink = if (selected) c.link else c.textMuted
            Column(Modifier.fillMaxWidth().heightIn(min = 64.dp)
                .sbFocusRing(interaction, t.radius.control)
                .focusRequester(focuses[index])
                .onPreviewKeyEvent { event ->
                    val step = when (event.key) {
                        Key.DirectionDown -> 1
                        Key.DirectionUp -> -1
                        Key.DirectionRight -> if (direction == LayoutDirection.Ltr) 1 else -1
                        Key.DirectionLeft -> if (direction == LayoutDirection.Ltr) -1 else 1
                        else -> 0
                    }
                    val next = when {
                        event.key == Key.MoveHome -> 0
                        event.key == Key.MoveEnd -> items.lastIndex
                        step != 0 -> (index + step + items.size) % items.size
                        else -> null
                    }
                    if (next == null) false else {
                        if (event.type == KeyEventType.KeyDown) { focuses[next].requestFocus(); onSelect(next) }
                        true
                    }
                }
                .selectable(selected, interactionSource = interaction, indication = null, role = Role.Tab,
                    onClick = { onSelect(index) })
                .drawBehind {
                    if (selected) drawRect(c.accent,
                        topLeft = Offset(if (layoutDirection == LayoutDirection.Ltr) 0f else size.width - 3.dp.toPx(), 0f),
                        size = Size(3.dp.toPx(), size.height))
                }.padding(horizontal = 4.dp, vertical = 8.dp),
                horizontalAlignment = Alignment.CenterHorizontally,
                verticalArrangement = Arrangement.spacedBy(2.dp, Alignment.CenterVertically)) {
                Icon(if (selected) item.selectedIcon else item.icon, null, Modifier.size(24.dp), tint = ink)
                SbWrapText(item.label, if (selected) ty.labelSmall.copy(fontWeight = ty.title.fontWeight) else ty.labelSmall,
                    ink, center = true)
            }
        }
    }
}
